import{_ as a,o as i,c as n,a3 as p}from"./chunks/framework.DdpBa4_E.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/programmer-essential/06-第06章—计算机的思维-代码的工作流程.md","filePath":"books/programmer-essential/06-第06章—计算机的思维-代码的工作流程.md","lastUpdated":1794316978000}'),t={name:"books/programmer-essential/06-第06章—计算机的思维-代码的工作流程.md"};function e(l,s,h,r,k,d){return i(),n("div",null,[...s[0]||(s[0]=[p(`<p>前面我们讲了二进制，讲了数据类型，那么这些东西都是怎么跑起来的呢？</p><p>其实，<code>代码就是用控制语句操作数据类型，实现自己的逻辑，然后交给计算器去执行</code>。其大概流程就是：<strong>我们用高级语言写的代码</strong> -&gt; <strong>编译成机器代码</strong> -&gt; <strong>读入内存中</strong> -&gt; <strong>CPU 执行</strong>。</p><p>这一系列操作需要调动 IO、控制器、运算器、寄存器、程序计数器等元件。我们就挨个来了解下这些元件的作用。</p><h2 id="计算机的元件" tabindex="-1">计算机的元件 <a class="header-anchor" href="#计算机的元件" aria-label="Permalink to &quot;计算机的元件&quot;">​</a></h2><p>众所周知，计算机是由<code>控制器</code>、<code>运算器</code>、<code>存储器</code>、<code>输入设备</code>、<code>输出设备</code>这五部分组成的，其中输入设备就是键盘和鼠标，输出设备就是显示器，这我们都见过了，那么控制器、运算器、存储器又是啥呢？CPU 又是啥玩意儿呢？我们来一一揭晓。</p><h3 id="控制器" tabindex="-1">控制器 <a class="header-anchor" href="#控制器" aria-label="Permalink to &quot;控制器&quot;">​</a></h3><blockquote><p>控制器是 CPU 的一部分，用来控制程序的执行流程。</p></blockquote><p><strong>程序计数器就是控制器的一部分</strong>。我们的代码被编译为机器码之后，就是从上到下逐行执行的，那么要执行哪一行，就是程序计数器来控制的。</p><p>比方说，我写了如下代码：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>那么，执行起来大概是这样：</p><p align="center"><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/5bb92e0cb4a448bb945471fa5fe60a1d~tplv-k3u1fbpfcp-watermark.image?" alt="211676823144_.pic.jpg"></p><p>在代码的执行过程中，每执行一行代码，程序计数器就会加 1，当执行的指令占据多个内存地址时，就会增加与指令长度相应的数值。然后，控制器就会参照程序计数器的数值，从内存中读取命令并执行。也就是说，程序计数器决定着程序的流程。</p><p>比如上述，程序计数器指向 0100 地址时，CPU 就读取这一行的指令，也就是：“将 a 读入寄存器”；由于这一行指令只占用一个内存地址，所以程序计数器只加 1，变成 0101；接着 CPU 就读取下一个地址 0101，然后将 b 读入寄存器；如此反复执行，直到程序结束。</p><h3 id="运算器" tabindex="-1">运算器 <a class="header-anchor" href="#运算器" aria-label="Permalink to &quot;运算器&quot;">​</a></h3><blockquote><p>运算器也是 CPU 的一部分，它和控制器共同组成 CPU。</p></blockquote><p>运算器的职责很简单，就是执行运算，比如上面的指令，执行到 0102 时，就需要将 a 和 b 相加，这个时候，运算器就会将两个寄存器的值，也就是 a 和 b 执行加法操作，然后将结果放入寄存器中，以备执行下一步。</p><p>运算器的原理很简单，就是使用我们高中都学过的门电路，举个例子，我们都知道按位与操作是：两个都为真才为真，那么，运算器怎么实现这个逻辑运算呢？</p><p>很简单，我们使用“串联”电路，我们构造一条电路，上面有多个开关，开关闭合表示“真”，开关打开表示“假”，这样，当所有开关都闭合，也就是所有条件都是“真”时，灯泡才亮，我们就当灯泡亮表示真，这就达到了“全真才真”的目的。同样的，或操作就可以使用“并联”电路，只要有一个开关闭合，也就是只要有一个条件为真，灯泡就会亮，这也达到了或操作的“一真则真”的目的。</p><p>用计算机来表示就是 1 表示灯泡亮，也就表示真；0 表示灯泡灭，也就是表示假。真是巧妙的设计！</p><p>有人说，运算器不是从内存中读数据的吗，怎么是从寄存器读数据呢？这跟我理解的不太一样啊。</p><h3 id="寄存器" tabindex="-1">寄存器 <a class="header-anchor" href="#寄存器" aria-label="Permalink to &quot;寄存器&quot;">​</a></h3><blockquote><p>寄存器是在 CPU 内的，也是 CPU 的一部分。</p></blockquote><p>因为寄存器是 CPU 的一部分，所以 CPU 从寄存器读写数据非常快，其实，我们通常说的：CPU 从内存中读数据，就是把数据读入寄存器中，但是我们的数据不是直接从内存读入寄存器的，而是先读入一个高速缓存中，然后才读入寄存器的。</p><p>这是为啥呢？因为从内存中读数据太慢了。</p><p>你可以这么理解：CPU 先把数据读入高速缓存中，以备使用，真正使用的时候，就从高速缓存中读入寄存器；当寄存器使用完毕后，就把数据写回到高速缓存中，然后高速缓存再在合适的时机将数据写入到存储器。</p><p>CPU 运算速度非常快，而从内存读数据非常慢，如果每次都从内存中读写数据，那么势必会拖累 CPU 的运算速度，可能执行 100s，有 99s 都在读取数据。为了解决这个问题，我们就在 CPU 和存储器之间放了个高速缓存，而 CPU 和高速缓存之间的读写速度是很快的，CPU 只管和高速缓存互相读写数据，而不管高速缓存和存储器之间是怎么同步数据的。这样就解决了内存读写慢的问题。</p><p>举个例子就是：我每次去书架拿书都很费劲，于是我就直接从书架把书取下来，放在我桌子上，这样就不用频繁去书架取了，等到读完了，就再把桌子上的书送回书架即可。</p><p>那这样有个问题啊，如果别人也想要书架上的那一本书怎么办？</p><p>问得好！这就是多线程问题，其实解决方案很简单，就是一个同步问题，要么你等我看完了再看，要么就多弄几本。这个问题我们在后面的操作系统部分再详细展开。</p><h2 id="程序的执行流" tabindex="-1">程序的执行流 <a class="header-anchor" href="#程序的执行流" aria-label="Permalink to &quot;程序的执行流&quot;">​</a></h2><p>经过上面的说明，我们大致了解了程序的执行过程：<strong>我们的代码先被编译成一条一条的指令，要执行的时候就先读入高速缓存，然后将要执行的指令地址放在程序计数器中，控制器控制着这些指令按序执行，遇到数据就读入寄存器来让运算器执行，执行完毕后就放回寄存器执行下一条，全部执行完毕后就把数据写回高速缓存，高速缓存在合适时机就将数据同步回内存。</strong></p><p>唉，等等等等，这好像不对啊，程序不一定是按顺序执行的，比如遇到<code>if-else</code>语句呢？遇到<code>return</code>语句呢？还会按顺序执行吗？</p><p>肯定不会，其实程序的执行流程可以分为：<strong>顺序执行、条件分支和循环执行</strong>这三种。</p><h3 id="条件分支和循环" tabindex="-1">条件分支和循环 <a class="header-anchor" href="#条件分支和循环" aria-label="Permalink to &quot;条件分支和循环&quot;">​</a></h3><p>考察如下代码:</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这个例子中有个条件分支，代码肯定不会顺序执行，那我们来看它是怎么执行的。</p><p align="center"><img src="https://p9-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/223aaf86b0d245ea86fdfe7aaec10971~tplv-k3u1fbpfcp-watermark.image?" alt="image.png"></p><p>我们看到，在执行到指令 0102 时候，由于不满足<code>a&gt;3</code>这个条件，就直接跳转到 0104 这个指令去执行了；而且，计算机很聪明，如果它在编译期间发现 a 永远不可能大于 3，它就会直接删除 0103 这条指令，然后，0104 这条指令就变成了下一条指令，直接顺序执行，也就是编译器的优化。</p><p>那么，计算机怎么知道 a 是不大于 3 呢？很简单，做减法，计算机使用 a-3，发现结果小于 0，就知道 a 小于 3 了。</p><p><strong>计算机中的比较操作，就是做减法，结果大于 0 就是大于，结果小于 0 就是小于，结果等于 0 就是相等</strong>。</p><p>其他的循环语句和跳转语句，也是类似的过程，这里不多废话。</p><p>上面我们讲的都是单个函数，那么如果是多个函数互相调用呢，会是什么样的结果呢？</p><h3 id="函数的调用流程" tabindex="-1">函数的调用流程 <a class="header-anchor" href="#函数的调用流程" aria-label="Permalink to &quot;函数的调用流程&quot;">​</a></h3><p>函数的调用需要用到函数的调用和返回指令，我们看个例子：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>代码的执行过程大概是如下这样：</p><p align="center"><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/84e90a6377054279bf4dde6abcf3f839~tplv-k3u1fbpfcp-watermark.image?" alt="image.png"></p><p>这里执行函数的时候，使用的是<code>call</code>指令，而不是<code>if-else</code>中的跳转指令，我们要注意，<strong>call 指令和 return 指令总是成对出现的，也就是说：有函数调用，就有函数返回</strong>。</p><p><code>call</code>指令会把调用函数后的下一条指令存入栈中，然后执行函数逻辑，在函数执行完后，<code>return</code>指令会把栈中的下一条指令弹出，并写入程序计数器中，这样就接着执行下一条指令了。又因为 call 和 return 是成对出现的，所以即使多个函数调用嵌套调用，也不会出现问题。</p><p>比如上述例子中，在执行到 0102 时候，<code>call</code>指令就把 0103 压入栈中，接着执行函数逻辑；当执行完毕后，<code>return</code>指令就把 0103 这个再弹出写回到程序计数器，这样程序计数器就接着执行 0103 对应的指令，程序就按照我们的逻辑执行了。如此一来，程序的执行非常有序且流畅。</p><h2 id="机器指令" tabindex="-1">机器指令 <a class="header-anchor" href="#机器指令" aria-label="Permalink to &quot;机器指令&quot;">​</a></h2><p>其实，CPU 的处理流程很简单，就是按照给定的指令去执行，CPU 的指令有以下几种。</p><ul><li><p><strong>数据传送指令</strong>：执行数据的读取操作，比如从寄存器读数据，将数据写入寄存器。</p></li><li><p><strong>运算指令</strong>：执行算数运算和逻辑运算，比如加法运算，按位与运算，比较运算。</p></li><li><p><strong>跳转指令</strong>：条件分支、循环、跳转等操作。</p></li><li><p><strong>调用/返回指令</strong>：函数调用/返回操作。</p></li></ul><p>这些指令可能包含很多汇编指令，但是就是这么几种类型，只要用以上这些指令，就能完成所有的程序流程。是不是很简单呢？</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本章我们讲解了控制器、运算器、寄存器的作用，以及程序的工作流程，其实，所有这些都可以用简单的几条指令来概括，我们只需要了解其原理即可，不必死记硬背。</p><table tabindex="0"><thead><tr><th>指令类型</th><th>功能</th></tr></thead><tbody><tr><td>数据传送指令</td><td>执行数据的读取操作，比如从寄存器读数据，将数据读入寄存器等</td></tr><tr><td>运算指令</td><td>执行算数运算和逻辑运算，比如加法运算，按位与运算，比较运算等</td></tr><tr><td>跳转指令</td><td>条件分支、循环、跳转等操作</td></tr><tr><td>调用/返回指令</td><td>函数调用/返回操作</td></tr></tbody></table><p>那么，下一节，我们就来看下该怎么优化我们的程序流，以让代码变得更高效。</p>`,60)])])}const g=a(t,[["render",e]]);export{c as __pageData,g as default};
